// lib/product-image.ts
// Resolves the artwork for a product. Demo catalogue images live in
// public/images/products/sku-XXXX.svg (generated by scripts/generate-product-images.py).
// Admin-supplied absolute paths (starting with "/") take priority.

export function productImage(sku: string, image?: string | null): string {
  if (image && image.startsWith('/')) return image;
  return `/images/products/${sku.toLowerCase()}.svg`;
}

export const HERO_IMAGE = '/images/hero-tools.svg';

export const CATEGORY_IMAGES: Record<string, string> = {
  'Power Tools': '/images/categories/power-tools.svg',
  'Hand Tools': '/images/categories/hand-tools.svg',
  'Accessories': '/images/categories/accessories.svg',
  'Safety': '/images/categories/safety.svg',
  'Measuring': '/images/categories/measuring.svg',
};
